DO $$ BEGIN
 IF (SELECT count(*) FROM catalog.ui_texts WHERE locale_code='en' AND is_active AND text_key IN('account.menu.home','account.settings.changed','account.settings.chat','account.settings.invalid','account.settings.language','account.settings.like','account.settings.match','account.settings.nakh','account.settings.notification_info','account.settings.notifications','account.settings.off','account.settings.on','account.settings.saved','account.settings.toggle','account.settings.visibility_info','account.settings.visibility_off','account.settings.visibility_on','profile.edit.birth_request','profile.edit.birth_year','profile.edit.changed','profile.edit.current','profile.edit.empty','profile.edit.gender','profile.edit.gender_request','profile.edit.goal','profile.edit.highlight','profile.edit.interests','profile.edit.invalid','profile.edit.location','profile.edit.multi','profile.edit.multi_optional','profile.edit.name','profile.edit.optional','profile.edit.photos','profile.edit.photos_help','profile.edit.preference','profile.edit.reply','profile.edit.request_change','profile.edit.request_row','profile.edit.request_sent','profile.edit.requests','profile.edit.requests_empty','profile.edit.saved','profile.edit.status.approved','profile.edit.status.cancelled','profile.edit.status.pending','profile.edit.status.rejected','profile.edit.summary','profile.edit.title'))<>49 THEN
  RAISE EXCEPTION 'Owned profile and settings texts are incomplete'; END IF;
 IF NOT EXISTS(SELECT 1 FROM catalog.ui_texts WHERE locale_code='en' AND text_key='profile.edit.summary' AND variables='["gender","goal","highlight","interests","location","name","preference","year"]'::jsonb) THEN
  RAISE EXCEPTION 'Owned profile summary variables are invalid'; END IF;
END $$;
